import {openDialog,environment,jsonRequest} from './ui-core.mjs';
import {dayKey,shiftDay,dateRange,demoUsage,demoQuery,csv} from './usage-core.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=n=>n==null?'未知':Number(n).toLocaleString('zh-CN'),money=n=>'¥'+Number(n||0).toFixed(4);
const basis={demo:'演示',legacy:'历史记录',telemetry_estimate:'遥测估算',rate_estimate:'单价估算',unpriced:'未计价',reported:'上报费用',usage_priced:'用量计价',reserved_estimate:'预留估算'};
let sharedSession=null;
let state={mode:'demo',tab:'overview',...dateRange(30),provider:'',model:'',customer:'',feature:'',source:'',project:'',offset:0},readKey='',epoch=0;
const samples=demoUsage();
export function usagePage(){return '<section id="usage-root" aria-label="用量历史"></section>'}
export function clearUsageSession(){sharedSession=null;readKey='';epoch++;state={mode:'demo',tab:'overview',...dateRange(30),provider:'',model:'',customer:'',feature:'',source:'',project:'',offset:0};}
export function bindUsage(shared=null){sharedSession=shared;if(shared){readKey=shared.key;state.mode='server'}const root=document.querySelector('#usage-root');if(root)mount(root)}
function params(){return new URLSearchParams({...state,limit:'50'})}
async function query(p){if(state.mode==='demo')return demoQuery(samples,p);return jsonRequest('/api/usage?'+p,{headers:{authorization:'Bearer '+readKey},cache:'no-store'},'此站点未提供用量 API。请在自部署的 AgentGuard 服务中打开此页。')}
function mount(root){
 const ticket=++epoch;
 environment(state.mode==='server'?(readKey?'用量 · 正在校验':'用量 · 未连接'):'用量 · 示例',state.mode==='server'?'验证服务端只读连接':'独立示例数据 · 不计入真实账本');
 root.innerHTML=`<div class="heading"><div><h1>用量历史</h1><p>按时间、模型和业务查看调用记录。日期以中国标准时间 UTC+8 统计。</p></div><div class="actions"><button class="button" data-refresh>刷新</button><button class="button" data-csv disabled>导出 CSV</button></div></div><div class="usage-toolbar"><div class="usage-tabs" aria-label="数据来源"><button data-mode="demo" aria-pressed="${state.mode==='demo'}">示例数据</button><button data-mode="server" aria-pressed="${state.mode==='server'}">服务端账本</button></div><span class="usage-mode">${state.mode==='demo'?'独立演示数据 · 不计入真实账本':'SQLite 账本 · 同源只读连接'}</span></div><div id="usage-auth"></div><form id="usage-filters" class="usage-filters"><div class="usage-presets">${[['1','今天'],['7','7 天'],['30','30 天'],['90','90 天'],['365','365 天'],['0','全部']].map(([v,l])=>`<button type="button" data-days="${v}" class="button">${l}</button>`).join('')}</div><div class="usage-fields"><label>开始日期<input type="date" name="from" value="${state.from}"></label><label>结束日期<input type="date" name="to" value="${state.to}"></label><label>来源<select name="source"><option value="">全部来源</option></select></label><label>项目<select name="project"><option value="">所有项目</option></select></label><label>模型<select name="modelKey"><option value="">所有模型</option></select></label><label>客户<select name="customer"><option value="">所有客户</option></select></label><label>功能<select name="feature"><option value="">所有功能</option></select></label><button class="button primary" type="submit">应用筛选</button><button class="button" type="button" data-reset>重置</button></div></form><div id="usage-message" role="status"></div><div class="usage-tabs usage-view-tabs" aria-label="用量视图">${[['overview','概览'],['models','模型'],['calls','调用明细']].map(([v,l])=>`<button data-tab="${v}" aria-pressed="${state.tab===v}">${l}</button>`).join('')}</div><div id="usage-results"><div class="empty">正在读取…</div></div>`;
 if(sharedSession)root.querySelector('[aria-label="数据来源"]')?.remove();
 const $=s=>root.querySelector(s),message=s=>$('#usage-message').textContent=s;
 root.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{state.mode=b.dataset.mode;state.offset=0;state.provider=state.model=state.customer=state.feature=state.source=state.project='';readKey='';mount(root)});
 $('[data-refresh]').onclick=()=>mount(root);
 root.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{state.tab=b.dataset.tab;state.offset=0;mount(root)});
 root.querySelectorAll('[data-days]').forEach(b=>b.onclick=()=>{Object.assign(state,dateRange(Number(b.dataset.days)),{offset:0});mount(root)});
 $('[data-reset]').onclick=()=>{Object.assign(state,dateRange(30),{provider:'',model:'',customer:'',feature:'',source:'',project:'',offset:0});mount(root)};
 $('#usage-filters').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),from=f.get('from'),to=f.get('to');if(from&&to&&from>to)return message('开始日期不能晚于结束日期');const [provider,model]=f.get('modelKey')?JSON.parse(f.get('modelKey')):['',''];Object.assign(state,{from,to,provider,model,customer:f.get('customer'),feature:f.get('feature'),source:f.get('source'),project:f.get('project'),offset:0});mount(root)};
 if(state.mode==='server'){
  $('#usage-auth').innerHTML=readKey?'<div class="note"><span id="usage-connection-status">正在验证只读账本连接。</span> 凭证仅保存在当前页面内存。 <button class="link" data-disconnect>断开连接</button></div>':'<form id="usage-login" class="usage-login"><label>只读访问密钥<input name="key" type="password" autocomplete="off" placeholder="输入服务端 READ_KEY" required></label><button class="button primary">读取账本</button><small>在自己的服务器配置 READ_KEY。此页面不会保存或上传密钥到其他地址。</small></form>';
  if(readKey)$('[data-disconnect]').onclick=()=>{if(sharedSession)return sharedSession.onLogout();readKey='';mount(root)};
  else{$('#usage-results').innerHTML='<div class="card empty">连接后显示真实用量。示例数据不会混入账本。</div>';$('#usage-login').onsubmit=e=>{e.preventDefault();readKey=new FormData(e.target).get('key');mount(root)};return}
 }
 const p=params();
 query(p).then(d=>{
  if(ticket!==epoch||!root.isConnected)return;
  if(state.mode==='server'){environment('用量 · 服务端','已验证 · 读取真实账本');$('#usage-connection-status').textContent='已连接只读账本。'}
  const options=(items,value)=>'<option value="">全部</option>'+items.map(x=>`<option value="${esc(x.value??x)}" ${(x.value??x)===value?'selected':''}>${esc(x.label??x)}</option>`).join('');
  $('[name="modelKey"]').innerHTML=options(d.options.models.map(m=>({value:JSON.stringify([m.provider,m.model]),label:m.provider+' / '+m.model})),state.model?JSON.stringify([state.provider,state.model]):'');
  for(const field of ['customer','feature','source','project'])$('[name="'+field+'"]').innerHTML=options(d.options[field+'s']||[],state[field]);
  const s=d.summary;message(`${s.unknown_usage||0} 条记录缺少完整 Token；${s.estimated_requests||0} 条费用为估算；${s.unpriced_requests||0} 条未计价，费用合计仅包含已知部分。${d.undated.count?'另有 '+d.undated.count+' 条全局历史记录无日期，仅在“全部”中计入。':''}`);
  $('#usage-results').innerHTML=state.tab==='overview'?overview(d):state.tab==='models'?modelTable(d):calls(d);
  root.querySelectorAll('[data-day]').forEach(b=>b.onclick=e=>{e?.preventDefault();state.from=state.to=b.dataset.day;state.offset=0;state.tab='calls';mount(root)});
  root.querySelectorAll('[data-model-filter]').forEach(b=>b.onclick=()=>{[state.provider,state.model]=JSON.parse(b.dataset.modelFilter);state.tab='calls';state.offset=0;mount(root)});
  if($('[data-prev]'))$('[data-prev]').onclick=()=>{state.offset=Math.max(0,state.offset-50);mount(root)};
  if($('[data-next]'))$('[data-next]').onclick=()=>{state.offset+=50;mount(root)};
  root.querySelectorAll('[data-call]').forEach(b=>b.onclick=()=>{
   const r=d.rows[Number(b.dataset.call)],dialog=openDialog('<h2>调用详情</h2><dl class="usage-detail">'+Object.entries({请求:r.event_id,任务:r.task_id,时间:r.at||'未知',供应商:r.provider,实际模型:r.model,请求模型:r.requested_model||'未知',客户:r.customer,功能:r.feature,来源:r.source,项目:r.project||'未分类',会话:r.session_id||'未知',缓存写入Token:num(r.cache_creation_tokens),推理Token:num(r.reasoning_tokens),输入Token:num(r.input_tokens),输出Token:num(r.output_tokens),缓存命中Token:num(r.cached_tokens),费用:r.basis==='unpriced'?'未计价':money(r.cost),计价依据:basis[r.basis]||r.basis,耗时:r.duration_ms==null?'未知':r.duration_ms+' ms',价格快照:r.pricing||'无'}).map(([k,v])=>'<dt>'+k+'</dt><dd>'+esc(v)+'</dd>').join('')+'</dl>');
  });
  $('[data-csv]').disabled=false;$('[data-csv]').onclick=async()=>{
   const button=$('[data-csv]');if(button.disabled)return;button.disabled=true;button.textContent='导出中…';const mode=state.mode;
   try{const all=[];for(let offset=0;offset<d.summary.requests;offset+=500){if(ticket!==epoch||mode!==state.mode||!root.isConnected)return;const page=new URLSearchParams(p);if(d.snapshot!==undefined)page.set('snapshot',String(d.snapshot));page.set('limit','500');page.set('offset',String(offset));const result=await query(page);all.push(...result.rows);if(result.rows.length<500)break}if(ticket!==epoch||!root.isConnected)return;const a=document.createElement('a'),url=URL.createObjectURL(new Blob([csv(all)],{type:'text/csv;charset=utf-8'}));a.href=url;a.download='agentguard-usage-'+mode+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){if(ticket===epoch&&root.isConnected)message('导出失败：'+e.message)}finally{button.disabled=false;button.textContent='导出 CSV'}
  };
 }).catch(e=>{if(ticket===epoch&&root.isConnected){message(e.message);$('#usage-results').innerHTML='<div class="card empty">未能读取账本，请检查服务地址与密钥。未切换为示例数据。</div>';if(state.mode==='server'){environment('用量 · 连接失败','请重新输入密钥或检查服务');$('#usage-auth').innerHTML='<button class="button" data-retry-login>重新输入密钥</button>';$('[data-retry-login]').onclick=()=>{if(sharedSession)return sharedSession.onLogout();readKey='';mount(root)}}}});
}
function overview(d){const s=d.summary,cache=s.cache_known_input>0?(100*(s.cached_tokens||0)/s.cache_known_input).toFixed(1)+'%':'未知';return '<div class="stats usage-stats">'+[['调用次数',num(s.requests)],['输入 Token',num(s.input_tokens)],['输出 Token',num(s.output_tokens)],['费用（CNY）',money(s.cost)],['任务数',num(s.tasks)],['活跃天数',num(s.active_days)],['调用成功率',s.requests?(s.successes/s.requests*100).toFixed(1)+'%':'—'],['缓存命中率',cache]].map(([l,v])=>`<div class="card stat"><div class="label">${l}</div><div class="value">${v}</div></div>`).join('')+'</div><p class="usage-caption">Token 为已知部分合计；缓存率仅按有缓存记录的输入计算。费用为记录金额，并非订阅账单。</p><section class="card"><div class="card-head"><h2>每日费用</h2><small>人民币 · 点击日期查看明细</small></div>'+trend(d.daily)+'</section><section class="card usage-calendar"><div class="card-head"><h2>365 天调用活动</h2><small>显示当前筛选结果 · 格子深浅表示调用次数</small></div>'+calendar(d.daily)+'</section>'}
function trend(daily){if(!daily.length)return '<div class="empty">所选时间没有调用记录</div>';let from=state.from||daily[0].day,to=state.to||daily.at(-1).day;const span=Math.round((Date.parse(to)-Date.parse(from))/86400000)+1;if(span>3660)return '<div class="empty">请将时间范围缩小到 10 年以内查看趋势。</div>';const map=new Map(daily.map(r=>[r.day,r.cost])),points=Array.from({length:span},(_,i)=>({day:shiftDay(from,i),cost:map.get(shiftDay(from,i))||0})),max=Math.max(.0001,...points.map(r=>r.cost));return '<div class="usage-trend"><svg viewBox="0 0 800 170" role="group" aria-label="每日费用趋势，选择日期查看调用">'+[0,1,2].map(i=>`<line x1="44" x2="780" y1="${20+i*55}" y2="${20+i*55}" stroke="#e7eaf0"/><text x="0" y="${24+i*55}" fill="#8c96a5" font-size="10">${(max*(1-i/2)).toFixed(2)}</text>`).join('')+'<polyline fill="none" stroke="#647da5" stroke-width="2" points="'+points.map((r,i)=>(44+i*736/Math.max(1,span-1))+','+(130-r.cost/max*110)).join(' ')+'"/>'+points.map((r,i)=>`<a href="#usage" data-day="${r.day}" aria-label="${r.day}，费用 ${money(r.cost)}，查看调用"><circle cx="${44+i*736/Math.max(1,span-1)}" cy="${130-r.cost/max*110}" r="${span<40?3:1}" fill="#647da5"><title>${r.day} ${money(r.cost)}</title></circle></a>`).join('')+`<text x="44" y="157" fill="#8c96a5" font-size="10">${from}</text><text x="710" y="157" fill="#8c96a5" font-size="10">${to}</text></svg></div>`}
function calendar(daily){const map=new Map(daily.map(r=>[r.day,r.requests])),today=dayKey(new Date()),first=shiftDay(today,-364),max=Math.max(1,...daily.map(r=>r.requests));return '<div class="usage-calendar-scroll"><div class="heat-grid">'+Array.from({length:365},(_,i)=>{const day=shiftDay(first,i),n=map.get(day)||0,level=n?Math.max(1,Math.ceil(n/max*4)):0;return `<button data-day="${day}" class="heat-cell level-${level}" title="${day} · ${n} 次调用" aria-label="${day}，${n} 次调用"></button>`}).join('')+'</div><div class="heat-labels"><span>'+first+'</span><span>少 ▫ ▪ 多</span><span>'+today+'</span></div></div>'}
function modelTable(d){return '<section class="card table-wrap"><table><thead><tr><th>供应商 / 模型</th><th>调用</th><th>输入 Token</th><th>输出 Token</th><th>缓存 Token</th><th>费用</th><th>费用占比</th><th></th></tr></thead><tbody>'+d.models.map(m=>`<tr><td><strong>${esc(m.model)}</strong><small>${esc(m.provider)}</small></td><td>${num(m.requests)}</td><td>${num(m.input_tokens)}</td><td>${num(m.output_tokens)}</td><td>${num(m.cached_tokens)}</td><td>${money(m.cost)}</td><td>${d.summary.cost?(m.cost/d.summary.cost*100).toFixed(1):0}%</td><td><button class="link" data-model-filter="${esc(JSON.stringify([m.provider,m.model]))}">查看调用 →</button></td></tr>`).join('')+(d.models.length?'':'<tr><td colspan="8" class="empty">没有匹配的模型用量</td></tr>')+'</tbody></table></section>'}
function calls(d){return '<section class="card table-wrap"><table><thead><tr><th>时间 / 任务</th><th>模型</th><th>客户 / 功能</th><th>输入 / 输出 Token</th><th>费用 / 依据</th><th>结果</th><th></th></tr></thead><tbody>'+d.rows.map((r,i)=>`<tr><td>${r.at?esc(new Date(r.at).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false})):'日期未知'}<small>${esc(r.task_id)}</small></td><td>${esc(r.model)}<small>${esc(r.provider)}</small></td><td>${esc(r.customer)}<small>${esc(r.feature)}</small></td><td>${num(r.input_tokens)} / ${num(r.output_tokens)}</td><td>${r.basis==='unpriced'?'未计价':money(r.cost)}<small>${basis[r.basis]||esc(r.basis)}</small></td><td><span class="badge ${r.status==='failed'?'failed':''}">${r.status==='failed'?'失败':'成功'}</span></td><td><button class="link" data-call="${i}">详情</button></td></tr>`).join('')+(d.rows.length?'':'<tr><td colspan="7" class="empty">没有匹配的调用记录</td></tr>')+'</tbody></table></section><div class="usage-pagination"><span>'+num(d.summary.requests)+' 条记录 · 当前 '+(d.rows.length?d.offset+1:0)+'–'+(d.offset+d.rows.length)+'</span><button class="button" data-prev '+(d.offset===0?'disabled':'')+'>上一页</button><button class="button" data-next '+(d.offset+d.rows.length>=d.summary.requests?'disabled':'')+'>下一页</button></div>'}
